create table assessments (archived bit not null, mini_quiz bit not null, published bit not null, class_room_id bigint not null, created_by_id bigint not null, id bigint not null auto_increment, topic_id bigint, version bigint not null, title varchar(255), primary key (id)) engine=InnoDB;
create table attempts (total_score float(53) not null, assessment_id bigint not null, id bigint not null auto_increment, student_id bigint not null, submitted_at datetime(6) not null, payload_hash varchar(64) not null, submission_key varchar(255) not null, primary key (id)) engine=InnoDB;
create table class_rooms (id bigint not null auto_increment, teacher_id bigint not null, join_code varchar(255) not null, name varchar(255), primary key (id)) engine=InnoDB;
create table enrollments (class_room_id bigint not null, student_id bigint not null, primary key (class_room_id, student_id)) engine=InnoDB;
create table learning_gaps (attempt_id bigint not null, id bigint not null auto_increment, student_id bigint not null, topic_id bigint not null, gap_type enum ('DIRECT','MISCONCEPTION','ROOT'), status enum ('DONE','PENDING','RESOLVED'), primary key (id)) engine=InnoDB;
create table learning_materials (archived bit not null, id bigint not null auto_increment, topic_id bigint not null, url_or_content varchar(12000), title varchar(255), type enum ('LESSON','LINK','PRACTICE','VIDEO'), primary key (id)) engine=InnoDB;
create table question_options (correct bit not null, id bigint not null auto_increment, question_id bigint not null, text varchar(2000), primary key (id)) engine=InnoDB;
create table questions (assessment_id bigint not null, id bigint not null auto_increment, topic_id bigint not null, explanation varchar(4000), text varchar(4000), difficulty enum ('EASY','HARD','MEDIUM'), primary key (id)) engine=InnoDB;
create table recommendations (order_index integer not null, gap_id bigint not null, id bigint not null auto_increment, material_id bigint not null, student_id bigint not null, explanation varchar(4000), status enum ('DONE','PENDING','RESOLVED'), primary key (id)) engine=InnoDB;
create table responses (correct bit not null, attempt_id bigint not null, id bigint not null auto_increment, question_id bigint not null, selected_option_id bigint not null, confidence_level enum ('FAIRLY_SURE','NOT_SURE','VERY_SURE'), primary key (id)) engine=InnoDB;
create table topic_prerequisites (prerequisite_id bigint not null, topic_id bigint not null, primary key (prerequisite_id, topic_id)) engine=InnoDB;
create table topic_results (score_percent float(53) not null, attempt_id bigint not null, id bigint not null auto_increment, topic_id bigint not null, mastery_level enum ('DEVELOPING','NEEDS_PRACTICE','STRONG'), primary key (id)) engine=InnoDB;
create table topics (id bigint not null auto_increment, teacher_id bigint not null, description varchar(4000), name varchar(255), primary key (id)) engine=InnoDB;
create table users (id bigint not null auto_increment, email varchar(255) not null, name varchar(255) not null, password_hash varchar(255) not null, role enum ('STUDENT','TEACHER') not null, primary key (id)) engine=InnoDB;
